    const dir = 'ltr';
    const {root, el} = await dsSetup(html`<md-gb-list-item>Recipe<button slot="trailing-actions" aria-label="Flag">F</button><button slot="trailing-actions" aria-label="Archive">A</button></md-gb-list-item>`, 'md-gb-list-item');
    const part = (selector: string) => el.shadowRoot!.querySelector<HTMLElement>(selector)!;
