    const centerOf = dsCenter;
    const press = dsPress;
    const reduceMotion = dsReduceMotion;
    void [root, part, press, drag, pointer, centerOf, reduceMotion, dir];
    const item = part('#item');
    drag(item, -80);
    await settle();
    // Toward the end in RTL: there are no leading actions to reveal.
    expect(el.revealed).toBe('');
